/// Parse `90s`, `5m`, `2h` into whole seconds.
pub fn parse(input: &str) -> Result<i64, ParseError> {
    let input = input.trim();
    let (digits, unit) = input.split_at(input.len() - 1);
    let n: i64 = digits.parse().map_err(|_| ParseError::InvalidDigit)?;
    match unit {
        "s" => Ok(n),
        "m" => Ok(n * 60),
        "h" => Ok(n * 3600),
        _ => Err(ParseError::UnknownUnit),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn parses_negative_durations() {
        assert_eq!(parse("-90s"), Ok(-90));
    }
}
